SELECT `user_id` , IFNULL(sum(`work_duration`),0) as `work_duration` , IFNULL(sum(`work_pay_duration`),0) as `work_pay_duration` , IFNULL(sum(`rest_duration`),0) as `rest_duration` , IFNULL(sum(`rest_pat_duration`),0) as `rest_pat_duration` , IFNULL(sum(`fest_duration`),0) as `fest_duration` , IFNULL(sum(`fest_oat_duration`),0) as `fest_oat_duration` FROM `work_overtime_ledger_advance` where `work_date` between #{period.begin} and #{period.end} and `status` in ('PASS', 'FINISHED') and `user_id` in
#{id}
group by `user_id`

